  ('07b876eb-f902-4bbe-8084-ca25b4ffadf5', '00000000-0000-4000-8000-000000000001', 'Teapot', 'Unknown artist — Art Institute of Chicago, object 216790. Public domain (CC0).', '{"ceramic","vivid"}', '00000000-0000-4000-8000-000000000001/07b876eb-f902-4bbe-8084-ca25b4ffadf5.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '35 hour'),
  ('07b99925-f27b-491b-aa3d-b7f5be3464c3', '00000000-0000-4000-8000-000000000001', 'From My Window at the Shelton, West', 'Alfred Stieglitz — Art Institute of Chicago, object 66555. Public domain (CC0).', '{"photography","cityscape","monochrome"}', '00000000-0000-4000-8000-000000000001/07b99925-f27b-491b-aa3d-b7f5be3464c3.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '36 hour'),
  ('08835a4d-7871-4daf-965b-a02991dbb7e1', '00000000-0000-4000-8000-000000000001', 'Mary Underwood, Olive Underwood and Susan Underwood', 'I wished to hold three presences within one oval of quiet gravity, each face sustained by restraint, dark dress, and pale collar. The gilded case and deep red velvet surround them like a private ceremony, making the portrait both intimate and formal, suspended in a stillness that feels older than a moment.

