  ('0ed7621f-c6e0-41f7-af4a-3a0112956265', '00000000-0000-4000-8000-000000000001', 'Miniature Tray', 'Inca — Art Institute of Chicago, object 91506. Public domain (CC0).', '{"ceramic","monochrome","black and white"}', '00000000-0000-4000-8000-000000000001/0ed7621f-c6e0-41f7-af4a-3a0112956265.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '54 hour'),
  ('0f13e628-3738-4399-a4ec-dbfbc29baef0', '00000000-0000-4000-8000-000000000001', 'Coal Miner', 'I wanted this portrait to hold an unguarded moment of happiness, caught in a face brightened by weather, work, and youth. The cap, collar, and worn coat keep the figure grounded in an everyday world, while the soft focus and pale background let the smile carry the whole presence of the piece.

Lewis Wickes Hine — Art Institute of Chicago, object 23166. Public domain (CC0).', '{"photography","desaturated","realism","joyful"}', '00000000-0000-4000-8000-000000000001/0f13e628-3738-4399-a4ec-dbfbc29baef0.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '55 hour'),
