  ('2c0da8b9-2016-4671-b8ea-de28c6211d0d', '00000000-0000-4000-8000-000000000001', 'Thomas Walker and Peter Monamy', 'Gawen Hamilton — Art Institute of Chicago, object 28102. Public domain (CC0).', '{"oil painting","interior","portrait","vivid"}', '00000000-0000-4000-8000-000000000001/2c0da8b9-2016-4671-b8ea-de28c6211d0d.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '168 hour'),
  ('2c4b026b-0f7a-47b5-8ef2-3f595f855c22', '00000000-0000-4000-8000-000000000001', 'Portrait Bust of Antinous as Osiris', 'Ancient Roman — Art Institute of Chicago, object 230470. Public domain (CC0).', '{"sculpture","monochrome"}', '00000000-0000-4000-8000-000000000001/2c4b026b-0f7a-47b5-8ef2-3f595f855c22.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '169 hour'),
  ('2caf888f-a66a-46bf-92d5-77e299ca084d', '00000000-0000-4000-8000-000000000001', 'Untitled', 'I frame a cluster of work-worn men gathered around a wagon, their hats, hands, and angled bodies arranging a small theatre of conversation. The street supplies its own drama: rough pavement, shadowed canvas, and weathered buildings hold the encounter between commerce and companionship, caught in a pause that feels both ordinary and charged.

Lewis Wickes Hine — Art Institute of Chicago, object 23205. Public domain (CC0).', '{"photography","monochrome","realism","contemplative"}', '00000000-0000-4000-8000-000000000001/2caf888f-a66a-46bf-92d5-77e299ca084d.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '170 hour'),
