  ('2e50e485-7aae-46a7-b263-d713e6ac23c5', '00000000-0000-4000-8000-000000000001', 'Rhyton (Drinking Vessel) in the Shape of a Donkey Head', 'Ancient Greek — Art Institute of Chicago, object 40887. Public domain (CC0).', '{"ceramic","animal","monochrome"}', '00000000-0000-4000-8000-000000000001/2e50e485-7aae-46a7-b263-d713e6ac23c5.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '180 hour'),
