  ('39d47089-f888-4aa8-87db-9899fecfe12d', '00000000-0000-4000-8000-000000000001', 'Canopy for Bed Set', 'Unknown artist — Art Institute of Chicago, object 238625. Public domain (CC0).', '{"textile","muted","red dominant"}', '00000000-0000-4000-8000-000000000001/39d47089-f888-4aa8-87db-9899fecfe12d.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '218 hour'),
  ('39dcbda8-6b8c-4948-8518-f596409fdbdb', '00000000-0000-4000-8000-000000000001', 'Head of a Woman', 'I shaped this small head from clay with the hand still present in the surface, leaving the face quiet, unfinished, and close to the body of the work. The bust rises from a dark, simple support, giving the fragile modeled head a sense of gravity and stillness.

