  ('52f83008-363e-4cf4-bad6-c96251a381bd', '00000000-0000-4000-8000-000000000001', 'Dealer in Fancy-Ware', 'John Thomson — Art Institute of Chicago, object 215530. Public domain (CC0).', '{"photography","vivid","red dominant"}', '00000000-0000-4000-8000-000000000001/52f83008-363e-4cf4-bad6-c96251a381bd.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '325 hour'),
