  ('53cd2e5d-988a-47f0-85d2-b1abae98cbe4', '00000000-0000-4000-8000-000000000001', 'The Madame B Album', 'Marie-Blanche Hennelle Fournier — Art Institute of Chicago, object 201086. Public domain (CC0).', '{"photography","vivid"}', '00000000-0000-4000-8000-000000000001/53cd2e5d-988a-47f0-85d2-b1abae98cbe4.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '332 hour'),
  ('53e03974-be07-49b0-911b-d9a34ac59909', '00000000-0000-4000-8000-000000000001', 'Handled Jar Depicing Abstract Bird', 'I give the vessel a rounded, listening body, carrying a bird presence drawn in bold, pared-back marks. The painted figure feels both emblem and companion, standing at the center of the surface while dark bands and repeated strokes gather the eye into a steady rhythm. Its worn earthen ground and simplified anatomy keep the form close to clay, gesture, and ritual memory.

Nasca — Art Institute of Chicago, object 4801. Public domain (CC0).', '{"ceramic","vivid","figurative","illustrative","geometric","playful","contemplative"}', '00000000-0000-4000-8000-000000000001/53e03974-be07-49b0-911b-d9a34ac59909.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '333 hour'),
