  ('87debf52-cd60-4f87-bc22-edaf83fd5e7e', '00000000-0000-4000-8000-000000000001', 'Wide-Necked Bowl with Rows of Abstract Masks and Trophy Heads', 'Nasca — Art Institute of Chicago, object 91311. Public domain (CC0).', '{"ceramic","monochrome"}', '00000000-0000-4000-8000-000000000001/87debf52-cd60-4f87-bc22-edaf83fd5e7e.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '539 hour'),
  ('883671a5-fa57-42a8-9cdd-578e44e3f150', '00000000-0000-4000-8000-000000000001', 'Fragment', 'I conceived the surface as a woven field of disciplined repetition, where each motif sits like a small emblem within a measured grid. The worn edges and softened color carry the passage of time, while the rhythmic interlacing keeps the fragment both architectural and intimate.

Unknown artist — Art Institute of Chicago, object 2040. Public domain (CC0).', '{"textile","vivid","red dominant","geometric","abstract","solemn","contemplative"}', '00000000-0000-4000-8000-000000000001/883671a5-fa57-42a8-9cdd-578e44e3f150.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '540 hour'),
