  ('88e8bda3-b9a7-4b02-afbc-ebd36fd226ec', '00000000-0000-4000-8000-000000000001', 'A Talk with the Keeper', 'Henry Peach Robinson — Art Institute of Chicago, object 105331. Public domain (CC0).', '{"photography","landscape","vivid"}', '00000000-0000-4000-8000-000000000001/88e8bda3-b9a7-4b02-afbc-ebd36fd226ec.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '544 hour'),
  ('895f3a0d-f12f-41af-b19a-7a618c234417', '00000000-0000-4000-8000-000000000001', 'Bowl with Three Boys amid Peony Scrolls', 'Unknown artist — Art Institute of Chicago, object 50025. Public domain (CC0).', '{"ceramic","monochrome"}', '00000000-0000-4000-8000-000000000001/895f3a0d-f12f-41af-b19a-7a618c234417.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '545 hour'),
  ('89c00975-7ea2-4a3a-97e2-ba7c5a265af6', '00000000-0000-4000-8000-000000000001', 'Labourers', 'George Stubbs — Art Institute of Chicago, object 210864. Public domain (CC0).', '{"etching","animal","muted"}', '00000000-0000-4000-8000-000000000001/89c00975-7ea2-4a3a-97e2-ba7c5a265af6.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '546 hour'),
  ('8abcfa97-3f60-410e-a4eb-0be4def0c81b', '00000000-0000-4000-8000-000000000001', 'Figure Seated on Lotus, from a Set of Initiation Cards (Tsakali)', 'Unknown artist — Art Institute of Chicago, object 146859. Public domain (CC0).', '{"watercolour","muted"}', '00000000-0000-4000-8000-000000000001/8abcfa97-3f60-410e-a4eb-0be4def0c81b.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '547 hour'),
  ('8aea652a-9b6e-43fd-afd4-7b2822f12358', '00000000-0000-4000-8000-000000000001', 'The Fallen Caryatid Carrying Her Stone', 'I shaped the figure as a body bowed by weight, its strength and collapse held in the same gesture. The stone is not an addition but a fate: it presses the head down, bends the spine, and turns the pose into both endurance and surrender. I wanted the surface to keep the pressure of making—smooth where the body carries strain, rough where it seems to merge with the burden—so that the figure feels less like an idealized form than a living act of bearing.

Auguste Rodin — Art Institute of Chicago, object 11321. Public domain (CC0).', '{"sculpture","nude","muted","figurative","expressionist","gestural","solemn","melancholic"}', '00000000-0000-4000-8000-000000000001/8aea652a-9b6e-43fd-afd4-7b2822f12358.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '548 hour'),
