  ('8b3eef84-9ccd-44ad-8026-b0632b1825e1', '00000000-0000-4000-8000-000000000001', 'The Harvesters', 'Léon Augustin Lhermitte — Art Institute of Chicago, object 111746. Public domain (CC0).', '{"oil painting","landscape","muted"}', '00000000-0000-4000-8000-000000000001/8b3eef84-9ccd-44ad-8026-b0632b1825e1.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '550 hour'),
  ('8b8a8170-688e-435b-9a25-19668c016c9f', '00000000-0000-4000-8000-000000000001', 'Marchand du Panier', 'Jean-Eugène-Auguste Atget — Art Institute of Chicago, object 54282. Public domain (CC0).', '{"photography","vivid"}', '00000000-0000-4000-8000-000000000001/8b8a8170-688e-435b-9a25-19668c016c9f.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '551 hour'),
  ('8ba00966-3cba-4b05-8348-47bfc47f572b', '00000000-0000-4000-8000-000000000001', 'Stirrup Spout Vessel with Relief Depicting a Fishing Scene', 'I have shaped this ceramic vessel as a squat, breathing creature, its rounded body crowded with fishlike faces, fins, and mouths pressed into the surface as though the container itself were alive. The long spout rises like a neck or reed, making function feel ritual and bodily; the earth-toned surface gathers wear in its ridges and hollows, leaving the forms tender, watchful, and faintly uncanny.

Moche — Art Institute of Chicago, object 6314. Public domain (CC0).', '{"ceramic","monochrome","figurative","folk art","eerie","contemplative"}', '00000000-0000-4000-8000-000000000001/8ba00966-3cba-4b05-8348-47bfc47f572b.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '552 hour'),
