  ('a154907b-02f9-4642-bfd5-bf477623ae96', '00000000-0000-4000-8000-000000000001', 'The Madame B Album', 'Marie-Blanche Hennelle Fournier — Art Institute of Chicago, object 200913. Public domain (CC0).', '{"photography","desaturated"}', '00000000-0000-4000-8000-000000000001/a154907b-02f9-4642-bfd5-bf477623ae96.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '639 hour'),
  ('a190fa6a-b03f-4950-a53d-4779993b514c', '00000000-0000-4000-8000-000000000001', 'Fragment', 'I wanted the pattern to feel both worked and worn, a quiet field of burgundy flowers laid into a pale ground, with the rhythm of the motif becoming almost a second surface. The dark red forms gather and recede like pressed leaves, giving the textile a handmade gravity without losing its decorative ease.

Unknown artist — Art Institute of Chicago, object 2016. Public domain (CC0).', '{"textile","muted","illustrative","serene","nostalgic"}', '00000000-0000-4000-8000-000000000001/a190fa6a-b03f-4950-a53d-4779993b514c.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '640 hour'),
