  ('a4cf23a3-5254-4556-bc06-c9073a20168e', '00000000-0000-4000-8000-000000000001', 'Fragment', 'Unknown artist — Art Institute of Chicago, object 90807. Public domain (CC0).', '{"textile","vivid","red dominant"}', '00000000-0000-4000-8000-000000000001/a4cf23a3-5254-4556-bc06-c9073a20168e.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '655 hour'),
  ('a540bcb0-6505-42ac-bb20-5d3ca3cca964', '00000000-0000-4000-8000-000000000001', 'Evening Glow at Seta (Seta sekisho), from the series "Fashionable Eight Views of Omi (Furyu Omi hakkei)"', 'Kikukawa Eizan — Art Institute of Chicago, object 33045. Public domain (CC0).', '{"vivid"}', '00000000-0000-4000-8000-000000000001/a540bcb0-6505-42ac-bb20-5d3ca3cca964.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '656 hour'),
  ('a5762ddf-bbd8-491d-b105-7ce22fa70acf', '00000000-0000-4000-8000-000000000001', 'Friar Pedro Binds El Maragato with a Rope', 'The work is a violent and intimate encounter: a cloaked figure protects a wounded man while another assailant advances in the background. The loose, forceful handling of paint and the stark, blood-red detail give the scene a raw emotional charge, balancing tenderness with brutality.

Francisco José de Goya y Lucientes — Art Institute of Chicago, object 16365. Public domain (CC0).', '{"oil painting","crowd","botanical","vivid","figurative","expressionist","dramatic","tense"}', '00000000-0000-4000-8000-000000000001/a5762ddf-bbd8-491d-b105-7ce22fa70acf.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '657 hour'),
  ('a59b4b5b-de95-44cf-8524-0a93d95cedec', '00000000-0000-4000-8000-000000000001', 'L''Hiver (Winter, plate four from Le Quatre Saisons)', 'Charles-Joseph Natoire — Art Institute of Chicago, object 141424. Public domain (CC0).', '{"etching","desaturated"}', '00000000-0000-4000-8000-000000000001/a59b4b5b-de95-44cf-8524-0a93d95cedec.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '658 hour'),
  ('a5b85b2a-b13b-4409-b332-3336571a8dfc', '00000000-0000-4000-8000-000000000001', 'Bowl Depicting a Female Figure with Shield and Darts Motifs', 'Teotihuacan — Art Institute of Chicago, object 30739. Public domain (CC0).', '{"ceramic","monochrome","black and white"}', '00000000-0000-4000-8000-000000000001/a5b85b2a-b13b-4409-b332-3336571a8dfc.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '659 hour'),
  ('a670b855-fa5e-49b8-abb8-380d7d5d49ae', '00000000-0000-4000-8000-000000000001', 'San Gimignano, Piazza Cavour cis della cisterna', 'I framed the square as a quiet field of old stone, where weight, weather, and time gather around the central well. The narrow streets and towers lean into the open space, giving the scene a measured stillness, while the faded light softens the architecture into something both documentary and reverent.

Unknown — Art Institute of Chicago, object 23016. Public domain (CC0).', '{"photography","muted","realism","nostalgic","contemplative"}', '00000000-0000-4000-8000-000000000001/a670b855-fa5e-49b8-abb8-380d7d5d49ae.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '660 hour'),
  ('a693bdb6-7fd1-4012-a0f5-055b7b32deb4', '00000000-0000-4000-8000-000000000001', 'Landscape with Hunters', null, '{}', '00000000-0000-4000-8000-000000000001/a693bdb6-7fd1-4012-a0f5-055b7b32deb4.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '661 hour'),
