  ('b428d8be-6d6e-4c2b-ba21-3c81f7a596bf', '00000000-0000-4000-8000-000000000001', 'Portrait of Myself', 'Theodore Roussel — Art Institute of Chicago, object 210958. Public domain (CC0).', '{"desaturated"}', '00000000-0000-4000-8000-000000000001/b428d8be-6d6e-4c2b-ba21-3c81f7a596bf.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '702 hour'),
  ('b430e65d-507c-45d5-95e7-e46322697a40', '00000000-0000-4000-8000-000000000001', 'Fragment', 'Unknown artist — Art Institute of Chicago, object 93024. Public domain (CC0).', '{"textile","vivid"}', '00000000-0000-4000-8000-000000000001/b430e65d-507c-45d5-95e7-e46322697a40.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '703 hour'),
  ('b43ac92c-a202-414b-9693-086485197b08', '00000000-0000-4000-8000-000000000001', 'Cameo with Head of a Man', 'Wedgwood Manufactory — Art Institute of Chicago, object 67836. Public domain (CC0).', '{"sculpture","ceramic","vivid"}', '00000000-0000-4000-8000-000000000001/b43ac92c-a202-414b-9693-086485197b08.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '704 hour'),
  ('b48d9a7a-3717-4917-b23b-71f8e480f506', '00000000-0000-4000-8000-000000000001', 'Still Life with Dead Game, Fruits, and Vegetables in a Market', 'Frans Snyders — Art Institute of Chicago, object 62042. Public domain (CC0).', '{"oil painting","still life","animal","food","bird","desaturated"}', '00000000-0000-4000-8000-000000000001/b48d9a7a-3717-4917-b23b-71f8e480f506.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '705 hour'),
  ('b4c9a1ca-0254-4109-9331-61f384a69201', '00000000-0000-4000-8000-000000000001', 'Pacing Horse (one of a pair)', 'I shape the horse as a study in quiet strength, giving the body a measured dignity rather than a moment of frantic motion. The dark surface gathers light along the shoulder, flank, and mane, while the saddle and ornate base give the figure a formal, enduring presence.

Giovanni da Bologna — Art Institute of Chicago, object 12702. Public domain (CC0).', '{"sculpture","animal","monochrome","realism","solemn"}', '00000000-0000-4000-8000-000000000001/b4c9a1ca-0254-4109-9331-61f384a69201.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '706 hour'),
  ('b4e4d251-576c-4d98-986f-a95ed2e1cf0e', '00000000-0000-4000-8000-000000000001', 'Ange Laurent de Lalive de Jully', 'After Jean Baptiste Greuze — Art Institute of Chicago, object 109885. Public domain (CC0).', '{"oil painting","portrait","desaturated"}', '00000000-0000-4000-8000-000000000001/b4e4d251-576c-4d98-986f-a95ed2e1cf0e.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '707 hour'),
  ('b4ea9585-6232-4780-8f5b-7b8083454077', '00000000-0000-4000-8000-000000000001', 'Milk Jug', 'Unknown artist — Art Institute of Chicago, object 216815. Public domain (CC0).', '{"ceramic","vivid"}', '00000000-0000-4000-8000-000000000001/b4ea9585-6232-4780-8f5b-7b8083454077.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '708 hour'),
