  ('bf3c5375-57c6-4738-bafc-2407b09ed1d5', '00000000-0000-4000-8000-000000000001', 'Bowl with Radiating Striped Bands and Triangles and Interlocking Zigzag on Exterior', 'Salado — Art Institute of Chicago, object 52108. Public domain (CC0).', '{"ceramic","monochrome"}', '00000000-0000-4000-8000-000000000001/bf3c5375-57c6-4738-bafc-2407b09ed1d5.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '743 hour'),
  ('bf43658c-da0c-4758-9707-179a0d9f6992', '00000000-0000-4000-8000-000000000001', 'Fragment', 'I built this textile from dense, rhythmic ornament—flower, leaf, and vine pressed into a woven field of vertical and lattice-like structure. The design favors bold silhouette and pattern over naturalistic detail, letting the fabric itself become a garden of repeated, interlocking forms.

Unknown artist — Art Institute of Chicago, object 1933. Public domain (CC0).', '{"textile","floral","desaturated","folk art","art nouveau","serene","nostalgic"}', '00000000-0000-4000-8000-000000000001/bf43658c-da0c-4758-9707-179a0d9f6992.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '744 hour'),
