  ('c3368690-d14b-4c7a-b426-302739ef6b6a', '00000000-0000-4000-8000-000000000001', 'Lilie Stainers, 7 years old. Atlanta, Georgia', 'Lewis Wickes Hine — Art Institute of Chicago, object 59164. Public domain (CC0).', '{"photography","monochrome"}', '00000000-0000-4000-8000-000000000001/c3368690-d14b-4c7a-b426-302739ef6b6a.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '756 hour'),
  ('c34fa427-6f68-4ef4-bd5c-b37b4b2000d2', '00000000-0000-4000-8000-000000000001', 'Figurine of a Mother and Child', 'Siamese — Art Institute of Chicago, object 58521. Public domain (CC0).', '{"sculpture","ceramic","vivid","red dominant"}', '00000000-0000-4000-8000-000000000001/c34fa427-6f68-4ef4-bd5c-b37b4b2000d2.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '757 hour'),
  ('c3bf6f7b-3695-47c5-925e-17d9b7fdc2f9', '00000000-0000-4000-8000-000000000001', 'Beaker Depicting Rows of Abstract Human Heads', 'I shaped this vessel as a quiet container for gathering and remembering, its tapering body wrapped in bands of animal forms that press, turn, and reappear like a shared ritual language. The ochre interior contrasts with the darker ground, while repeated eyes, teeth, and sinuous bodies keep the surface both ordered and alive. I wanted the painting to feel ancient and immediate: patterned, rhythmic, and held together by the tension between restraint and movement.

Nasca — Art Institute of Chicago, object 4711. Public domain (CC0).', '{"ceramic","monochrome","figurative","geometric","folk art","solemn","contemplative"}', '00000000-0000-4000-8000-000000000001/c3bf6f7b-3695-47c5-925e-17d9b7fdc2f9.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '758 hour'),
