  ('e98dc44c-b135-4bd1-80ae-48d85be80364', '00000000-0000-4000-8000-000000000001', 'Versailles, Vase (Detail)', 'Jean-Eugène-Auguste Atget — Art Institute of Chicago, object 124215. Public domain (CC0).', '{"photography","monochrome"}', '00000000-0000-4000-8000-000000000001/e98dc44c-b135-4bd1-80ae-48d85be80364.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '922 hour'),
