  ('f7e2d893-5a79-46d9-b41b-8ce6ec5afe01', '00000000-0000-4000-8000-000000000001', 'Hind Head Hill, plate 25 from Liber Studiorum', 'Joseph Mallord William Turner — Art Institute of Chicago, object 50065. Public domain (CC0).', '{"etching","muted"}', '00000000-0000-4000-8000-000000000001/f7e2d893-5a79-46d9-b41b-8ce6ec5afe01.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '971 hour'),
  ('f7ffa2f0-e194-4a81-855a-d2c48eab6c86', '00000000-0000-4000-8000-000000000001', 'Hieroglyphic Panel', 'Maya — Art Institute of Chicago, object 33231. Public domain (CC0).', '{"sculpture","monochrome"}', '00000000-0000-4000-8000-000000000001/f7ffa2f0-e194-4a81-855a-d2c48eab6c86.jpg', timestamptz '2026-01-01 00:00:00+00' + interval '972 hour'),
  ('f82b8bc7-c14f-4832-a931-2c4b3971cec8', '00000000-0000-4000-8000-000000000001', 'Panel', 'I developed this work as a field of layered blues and greens, where repeated botanical forms emerge and recede through rhythm and ornament. The surface is built from curling stems, softened blossoms, and dense woven patterns, more concerned with resonance than narrative. I wanted the textile to feel ceremonial yet weathered, carrying the quiet gravity of age, touch, and inherited design.

